"""Hotel Incomplete Work on the test copy: the work itself still works under the grouped list — an item added by hand lands under
its kind's heading, the search narrows, closing with a note moves it to Done, reopening brings it back, Refresh runs the detectors."""
import asyncio, os, sys, re, time, json; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from tc import *
async def close_modal(pg, sel):
    await pg.locator(sel + " [data-bs-dismiss='modal']").first.click()
    await pg.wait_for_function("(sel) => !document.querySelector(sel).classList.contains('show') && !document.querySelector('.modal-backdrop')", arg=sel, timeout=5000)
async def main():
    async with async_playwright() as p:
        b, ctx = await browser(p)
        pg, body = await login(ctx, "admin")
        W = BASE + "master_files/hotel_work"
        errs = []; pg.on("pageerror", lambda e: errs.append(str(e)) if str(e) != "Failed to fetch" else None)
        await pg.goto(W, wait_until="load"); await pg.wait_for_selector("#items tr.item", timeout=30000); await pg.wait_for_timeout(1000)
        n0 = await pg.locator("#items tr.item").count(); g0 = await pg.locator("#items tr.grp").count()
        check("the open list shows, grouped", n0 > 0 and g0 > 0, (n0, g0))
        await pg.click("#btn_add"); await pg.wait_for_selector("#m_add.show", timeout=5000)
        T = "1c test %d: Perahera dates missing" % int(time.time())   # a fresh title each run: the queue keeps the earlier runs' items (ignored), nothing is deleted
        await pg.fill("#a_title", T); await pg.fill("#a_detail", "Ask the hotel for the 2026 Perahera nights."); await pg.fill("#a_acc", "6-9-11-T101")
        await pg.click("#a_save"); await pg.wait_for_timeout(1500)
        row = pg.locator("#items tr.item").filter(has_text=T)
        check("an item added by hand appears, marked 'added by hand'", await row.count() == 1 and "added by hand" in (await row.text_content()))
        heading = await pg.evaluate("((T) => { const r = Array.from(document.querySelectorAll('#items tr')).find(t => t.textContent.includes(T)); let h = r; while (h && !h.classList.contains('grp')) h = h.previousElementSibling; return h ? h.textContent.replace(/\\s+/g,' ').trim() : ''; })", T)
        check("it sits under its kind's heading (the heading names the kind and counts it)", heading != "" and re.search(r"\d+ items?$", heading), heading)
        await pg.fill("#f_q", "Perahera dates missing"); await pg.wait_for_timeout(900)
        check("the search narrows the list to that item, one heading above it", await pg.locator("#items tr.item").count() == 1 and await pg.locator("#items tr.grp").count() == 1)
        wid = await pg.get_attribute("#items tr.item", "data-id")
        await pg.locator("#items tr.item [data-act='done']").first.click(); await pg.wait_for_selector("#m_resolve.show", timeout=5000)
        await pg.fill("#m_resolve_note", "Dates received from the hotel"); await pg.click("#m_resolve_ok"); await pg.wait_for_timeout(1500)
        check("closing it with a note removes it from the open list (and its heading goes with it)", await pg.locator("#items tr.item").count() == 0 and await pg.locator("#items tr.grp").count() == 0)
        await pg.select_option("#f_status", "done"); await pg.wait_for_timeout(1000)
        txt = await pg.text_content("#items")
        check("under Done it shows with who closed it and the note", T in txt and "Dates received from the hotel" in txt and "Done by" in txt, txt[:200])
        await pg.locator("#items tr.item [data-act='open']").first.click(); await pg.wait_for_selector("#m_resolve.show", timeout=5000); await pg.click("#m_resolve_ok"); await pg.wait_for_timeout(1200)
        st = await pg.evaluate("fetch('%s/list?status=open&q=' + encodeURIComponent(%s), {headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.json()).then(j=>j.data.items.length)" % (W, json.dumps(T)))
        check("it can be reopened", st == 1, st)
        await pg.evaluate("fetch('%s/item/' + %s + '/status', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({status:'ignored', note:'1c test cleanup'})})" % (W, wid))
        j = await pg.evaluate("fetch('%s/scan', {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}).then(r=>r.json())" % W)
        check("Refresh runs every detector and reports", j["status"] == 200 and "Scan finished" in j["message"], j.get("message"))
        await pg.fill("#f_q", ""); await pg.select_option("#f_status", "open"); await pg.wait_for_timeout(1200)
        check("the full open list is back as it was", await pg.locator("#items tr.item").count() == n0 and await pg.locator("#items tr.grp").count() == g0, (await pg.locator("#items tr.item").count(), n0))
        await pg.click("#btn_export"); await pg.wait_for_selector("#m_export.show", timeout=5000); await pg.wait_for_timeout(600)
        ex = await pg.input_value("#export_text")
        check("the export still lists the open items under their kinds", "Hotel Incomplete Work" in ex and len(ex) > 500, ex[:80])
        await close_modal(pg, "#m_export")
        check("no JS errors", not errs, errs[:3])
        await b.close()
    raise SystemExit(summary())
asyncio.run(main())
